--
-- Table structure for table `booking_payments`
--

DROP TABLE IF EXISTS `booking_payments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `booking_payments` (
  `booking_payments_id` int NOT NULL AUTO_INCREMENT,
  `booking_id` int NOT NULL,
  `payment_type` enum('gpay','cash','bank','upi','cc','dc') NOT NULL DEFAULT 'gpay',
  `payment_amount` decimal(10,2) NOT NULL,
  `payment_date` date NOT NULL DEFAULT (curdate()),
  `payment_to` int NOT NULL,
  `payment_for` enum('advance','part-pay','balance','refund') NOT NULL DEFAULT 'advance',
  `payment_added_by` int NOT NULL,
  `remarks` text,
  PRIMARY KEY (`booking_payments_id`),
  KEY `booking_id` (`booking_id`),
  KEY `payment_to` (`payment_to`),
  KEY `payment_added_by` (`payment_added_by`),
  CONSTRAINT `booking_payments_ibfk_1` FOREIGN KEY (`booking_id`) REFERENCES `bookings` (`booking_id`) ON DELETE CASCADE,
  CONSTRAINT `booking_payments_ibfk_2` FOREIGN KEY (`payment_to`) REFERENCES `users` (`user_id`) ON DELETE CASCADE,
  CONSTRAINT `booking_payments_ibfk_3` FOREIGN KEY (`payment_added_by`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=235 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

