--
-- Table structure for table `bookings`
--

DROP TABLE IF EXISTS `bookings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bookings` (
  `booking_id` int NOT NULL AUTO_INCREMENT,
  `customer_id` int NOT NULL,
  `room_id` int NOT NULL,
  `number_of_people` int NOT NULL DEFAULT '3',
  `check_in` date NOT NULL,
  `check_out` date NOT NULL,
  `status` enum('confirmed','cancelled','checked_in','checked_out') NOT NULL DEFAULT 'confirmed',
  `booking_date` date DEFAULT (curdate()),
  `booked_by_id` int NOT NULL,
  `source_of_booking_id` int DEFAULT NULL,
  `room_price` decimal(10,2) NOT NULL DEFAULT '0.00',
  `food_price` decimal(10,2) NOT NULL DEFAULT '0.00',
  `service_price` decimal(10,2) NOT NULL DEFAULT '0.00',
  `tax_percent` decimal(10,2) NOT NULL DEFAULT '0.00',
  `tax_price` decimal(10,2) NOT NULL DEFAULT '0.00',
  `discount_price` decimal(10,2) NOT NULL DEFAULT '0.00',
  `total_price` decimal(10,2) NOT NULL DEFAULT '0.00',
  `commission_percent` decimal(10,2) NOT NULL DEFAULT '0.00',
  `commission` decimal(10,2) NOT NULL DEFAULT '0.00',
  `is_commission_settled` tinyint(1) NOT NULL DEFAULT '0',
  `remarks` text,
  PRIMARY KEY (`booking_id`),
  KEY `room_id` (`room_id`),
  KEY `customer_id` (`customer_id`),
  KEY `booked_by_id` (`booked_by_id`),
  KEY `source_of_booking_id` (`source_of_booking_id`),
  CONSTRAINT `bookings_ibfk_1` FOREIGN KEY (`room_id`) REFERENCES `rooms` (`room_id`) ON DELETE CASCADE,
  CONSTRAINT `bookings_ibfk_2` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`customer_id`) ON DELETE CASCADE,
  CONSTRAINT `bookings_ibfk_3` FOREIGN KEY (`booked_by_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE,
  CONSTRAINT `bookings_ibfk_4` FOREIGN KEY (`source_of_booking_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=274 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

